import OpenAI from 'openai';

const openai = new OpenAI({
  baseURL: 'http://localhost:8000/v1',
  apiKey: 'sk-no-key-required'
});

async function main() {
  const response = await openai.embeddings.create({
    model: 'bge-m3-onnx',
    input: ['The quick brown fox jumps over the lazy dog', 'Artificial intelligence is transforming software']
  });
  console.log(`Generated ${response.data.length} embeddings!`);
  console.log(`Dimension: ${response.data[0].embedding.length}`);
}
main();

